// Guards: G4 register integration track separately from the default UAT suite; no test is hidden as a mock-only check.
import fs from 'node:fs'
const spec = 'tests/integration/intake-postgres.spec.mjs'
const guard = fs.readFileSync(spec, 'utf8').match(/^\/\/ Guards: (.+)$/m)[1]
const report = JSON.parse(fs.readFileSync('uat-artifacts/intake-integration.json', 'utf8'))
if (report.stats.unexpected || report.stats.expected !== 2) throw Error('Integration register requires both database-backed browser checks to pass')
process.stdout.write(`\n## Isolated intake PostgreSQL integration track\n\nGenerated by \`node tests/fixtures/intake-ui/register.mjs\` from the separate Playwright integration report. These two tests require the local SQL fixture and are outside the default UAT totals above.\n\n| Spec | Guards | Tests | Viewports | Acts on production | Status |\n|---|---|---|---|---|---|\n| ${spec} | ${guard} | 2 | desktop + phone | no | passing |\n`)
